 async function acceptIdentity(identity:LoggedInCustomer, matchChoice?:Record<string,string>) {
  if(savingDrafts)return;
  setVerifiedIdentity(identity);setSavingDrafts(true);setDraftSaveError("");
  try {
    const owned=await loadCustomerPets(identity.customerId);
    const drafts=pets.filter(p=>p.id.startsWith("draft:"));
    if(!matchChoice&&drafts.some(d=>owned.some(p=>p.species===d.species))){setOwnedMatches(owned);return;}
    const resolvedIds = new Map<string,string>();
    const used=new Set<string>();
    for (const pet of pets.filter(p=>p.id.startsWith("draft:"))) {
      const choice=matchChoice?.[pet.id];
      if(choice&&choice!=="new"){
        const existing=owned.find(p=>p.id===choice&&p.species===pet.species);
        if(!existing||used.has(existing.id))throw new Error("invalid_pet_match");
        used.add(existing.id);resolvedIds.set(pet.id,existing.id);continue;
      }
      const canonicalId=await guestPetIdentity(identity.customerId,pet.id);
      const mutationId=await guestPetIdentity(canonicalId,JSON.stringify(pet));
      const saved=await upsertCustomerPet({customerId:identity.customerId,idempotencyKey:`guest-pet:${mutationId}`,pet:{id:canonicalId,name:pet.name,species:pet.species,breed:pet.breed,vaccinationStatus:pet.vaccinationStatus,profile:pet.profile??undefined}});
      resolvedIds.set(pet.id,saved.entityId);
    }
    const loaded=await loadCustomerPets(identity.customerId);
    setPets(loaded);
    setSelectedPetIds(ids=>ids.map(id=>resolvedIds.get(id)??id).filter(id=>loaded.some(p=>p.id===id)));
    try{sessionStorage.removeItem(GUEST_GROOMING_DRAFT_KEY);}catch{}
    setOwnedMatches(null);setCustomer(identity);setVerifying(false);onVerified?.(identity);
  } catch {setDraftSaveError("Your phone is verified, but we couldn’t finish saving your pets. Your selections are still here. Retry to continue.");}
  finally { setSavingDrafts(false); }
 }
